p='observed_run/stdout.log'
for pat in ['validation','Validation','val/','val-','eval','Evaluation','accuracy','score']:
 print('\nPAT',pat)
 n=0
 for i,l in enumerate(open(p),1):
  if pat in l:
   print(i,l[:500].rstrip())
   n+=1
